-- Modify "kyc_applications" table
ALTER TABLE "seller"."kyc_applications" DROP CONSTRAINT "kyc_applications_purged_check", ADD CONSTRAINT "kyc_applications_purged_check" CHECK ((pii_purged_at IS NULL) OR ((real_name IS NULL) AND (birth_date IS NULL) AND (id_card_no_enc IS NULL) AND (id_card_hash IS NULL) AND (id_card_hash_key IS NULL) AND (id_card_issue_date IS NULL) AND (id_card_issue_type IS NULL) AND (id_card_issue_location IS NULL) AND (english_name IS NULL) AND (bank_name IS NULL) AND (bank_code IS NULL) AND (bank_account_enc IS NULL) AND (bank_account_hash IS NULL) AND (bank_account_hash_key IS NULL) AND (website_url IS NULL) AND (payout_contact_email IS NULL) AND (company_name IS NULL) AND (tax_id IS NULL) AND (tax_id_hash IS NULL) AND (tax_id_hash_key IS NULL) AND (company_register_date IS NULL) AND (company_town_code IS NULL) AND (company_address_detail IS NULL) AND (company_phone IS NULL) AND (rep_id_card_no_enc IS NULL) AND (rep_id_card_hash IS NULL) AND (rep_id_card_hash_key IS NULL))), ADD CONSTRAINT "kyc_applications_payout_contact_email_check" CHECK ((payout_contact_email = lower(payout_contact_email)) AND (char_length(payout_contact_email) <= 254) AND (payout_contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+$'::text)), ADD COLUMN "payout_contact_email" text NULL;
-- Modify "kyc_review_issues" table
ALTER TABLE "seller"."kyc_review_issues" DROP CONSTRAINT "kyc_review_issues_field_check", ADD CONSTRAINT "kyc_review_issues_field_check" CHECK (field = ANY (ARRAY['real_name'::text, 'birth_date'::text, 'id_card_issue_date'::text, 'id_card_issue_type'::text, 'id_card_issue_location'::text, 'english_name'::text, 'bank_name'::text, 'bank_code'::text, 'bank_account'::text, 'product_type'::text, 'website_url'::text, 'payout_contact_email'::text, 'id_card_front'::text, 'id_card_back'::text, 'bank_book'::text, 'individual.id_card_no'::text, 'business.company_name'::text, 'business.tax_id'::text, 'business.company_register_date'::text, 'business.company_address'::text, 'business.company_phone'::text, 'business.rep_id_card_no'::text, 'business.company_documents'::text]));
-- Modify "payment_accounts" table
ALTER TABLE "seller"."payment_accounts" ADD CONSTRAINT "payment_accounts_contact_email_check" CHECK ((contact_email = lower(contact_email)) AND (char_length(contact_email) <= 254) AND (contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+$'::text)), ADD COLUMN "contact_email" text NOT NULL;
